package dev.pocketengine.features.local.project;
import static org.junit.Assert.*;
import android.app.Application;import dev.pocketengine.features.*;import dev.pocketengine.features.local.LocalModule;import dev.pocketengine.features.local.runtime.*;import dev.pocketengine.features.workspace.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
/** Original manual owner module -> issued original FileSnapshot CAS -> actual retained bytes.
 * No TaskStore task/model account/process is needed or fabricated for this existing owner path. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=Application.class)
public final class ProjectBinaryImportNativeTest {
 private WorkspaceModule workspace;private LocalModule local;private String project,checkout;private Path files;private static final byte[] BEFORE={0,1,(byte)255,3};
 private static final class NoProcess implements ProjectRuntime {public JSONObject describe()throws Exception{return new JSONObject().put("runtimeId","manual_file_only").put("available",false).put("canExecute",false).put("phases",new JSONArray());}public RuntimeReceipt dispatch(RuntimeInvocation i){throw new AssertionError("manual import must not start process");}public RuntimeReceipt query(RuntimeExecutionRef r){throw new AssertionError("manual import must not query process");}public RuntimeReceipt requestCancel(RuntimeExecutionRef r){throw new AssertionError("manual import must not cancel process");}}
 @Before public void create()throws Exception{Application android=org.robolectric.RuntimeEnvironment.getApplication();FeatureContext context=new FeatureContext(android,null,null,event->{});workspace=new WorkspaceModule(context);project=workspace.handle("create",new JSONObject().put("name","Original manual binary version import")).getString("id");workspace.handle("write",new JSONObject().put("projectId",project).put("path","a.txt").put("expectedVersion",0).put("content","old\n"));workspace.writeBytesForHost(workspace.fileSnapshotForHost(project,"asset.bin",0),BEFORE);local=new LocalModule(context,workspace,new NoProcess());checkout=local.handle("prepare",new JSONObject().put("projectId",project)).getString("id");files=android.getFilesDir().toPath().resolve("local-development/checkouts/"+checkout+"/files");}
 @After public void close(){if(local!=null)local.close();if(workspace!=null)workspace.close();}
 private JSONObject input(String path)throws Exception{return new JSONObject().put("checkoutId",checkout).put("path",path);}
 private JSONObject review(String path)throws Exception{return local.handle("reviewFile",input(path));}
 private JSONObject apply(JSONObject review)throws Exception{return local.handle("importToProject",ProjectBinaryImport.payload(review));}
 private VersionedWorkspace.FileSnapshot head(String path)throws Exception{return workspace.fileSnapshotForHost(project,path,0);}
 private JSONObject changed(String path)throws Exception{JSONArray all=local.handle("changes",new JSONObject().put("checkoutId",checkout)).getJSONArray("files");for(int i=0;i<all.length();i++)if(path.equals(all.getJSONObject(i).getString("path")))return all.getJSONObject(i);return null;}
 @Test public void originalIssuedVersionCasRetainsExactBinaryAndReviewShowsOnlyMetadataAndLimitedHex()throws Exception{byte[] after=new byte[100];for(int i=0;i<after.length;i++)after[i]=(byte)i;Files.write(files.resolve("asset.bin"),after);JSONObject shown=review("asset.bin");assertTrue(ProjectBinaryImport.isReview(shown));assertFalse(shown.getBoolean("textDiff"));assertFalse(shown.getBoolean("contentAvailable"));assertFalse(shown.toString().contains("contentBase64"));assertFalse(shown.has("content"));assertEquals(1,shown.getInt("expectedVersion"));assertEquals(ProjectSources.sha256(BEFORE),shown.getString("expectedTargetHash"));assertEquals(64,shown.getJSONObject("sourcePreview").getInt("shownBytes"));assertTrue(shown.getJSONObject("sourcePreview").getBoolean("truncated"));assertEquals(128,shown.getJSONObject("sourcePreview").getString("hex").length());JSONObject receipt=apply(shown);assertEquals(ProjectBinaryImport.RECEIPT,receipt.getString("format"));assertEquals(2,receipt.getInt("version"));assertTrue(receipt.getBoolean("projectVersionCommitted"));assertTrue(receipt.getBoolean("checkoutBaselineUpdated"));assertFalse(receipt.getBoolean("replayAllowed"));assertArrayEquals(after,head("asset.bin").bytes());assertEquals("unchanged",changed("asset.bin").getString("change"));assertEquals(2,changed("asset.bin").getInt("sourceVersion"));String reopened=local.handle("prepare",new JSONObject().put("projectId",project)).getString("id");assertNotEquals(checkout,reopened);assertArrayEquals(after,Files.readAllBytes(files.getParent().getParent().resolve(reopened).resolve("files/asset.bin")));}
 @Test public void aNewBinarySourceBecomesAnOriginalVersionOnlyAfterTheExplicitByteReview()throws Exception{byte[] bytes={0,9,8};Files.write(files.resolve("new.bin"),bytes);JSONObject shown=review("new.bin");assertEquals(0,shown.getInt("expectedVersion"));assertEquals("absent",shown.getString("expectedTargetHash"));assertTrue(head("new.bin").tombstone);JSONObject receipt=apply(shown);assertEquals(1,receipt.getInt("version"));assertArrayEquals(bytes,head("new.bin").bytes());assertFalse(review("new.bin").getBoolean("importable"));}
 @Test public void sourceChangeAfterReviewDoesNotOverwriteTheOriginalVersion()throws Exception{Files.write(files.resolve("asset.bin"),new byte[]{0,8});JSONObject shown=review("asset.bin");byte[] newer={0,7};Files.write(files.resolve("asset.bin"),newer);assertThrows(SecurityException.class,()->apply(shown));assertEquals(1,head("asset.bin").version);assertArrayEquals(BEFORE,head("asset.bin").bytes());assertArrayEquals(newer,Files.readAllBytes(files.resolve("asset.bin")));}
 @Test public void targetVersionChangeAfterReviewKeepsTheNewerFormalVersion()throws Exception{Files.write(files.resolve("asset.bin"),new byte[]{0,8});JSONObject shown=review("asset.bin");byte[] newer={0,7};workspace.writeBytesForHost(head("asset.bin"),newer);assertThrows(SecurityException.class,()->apply(shown));assertEquals(2,head("asset.bin").version);assertArrayEquals(newer,head("asset.bin").bytes());}
 @Test public void oldTextParametersBodyInjectionAndChangedTargetIdentityCannotBecomeAByteImport()throws Exception{Files.write(files.resolve("asset.bin"),new byte[]{0,8});JSONObject shown=review("asset.bin"),valid=ProjectBinaryImport.payload(shown);JSONObject old=new JSONObject().put("checkoutId",checkout).put("path","asset.bin").put("expectedHash",shown.getString("expectedHash")).put("expectedVersion",shown.getInt("expectedVersion"));assertThrows(SecurityException.class,()->local.handle("importToProject",old));for(JSONObject bad:new JSONObject[]{new JSONObject(valid.toString()).put("contentBase64","AAAA"),new JSONObject(valid.toString()).put("expectedTargetHash","0".repeat(64)),new JSONObject(valid.toString()).put("expectedTargetRevisionId",UUID.randomUUID().toString()),new JSONObject(valid.toString()).put("projectId",UUID.randomUUID().toString())})assertThrows(SecurityException.class,()->local.handle("importToProject",bad));assertThrows(IllegalArgumentException.class,()->local.handle("importToProject",new JSONObject(valid.toString()).put("expectedVersion","1")));assertEquals(1,head("asset.bin").version);assertArrayEquals(BEFORE,head("asset.bin").bytes());}
 @Test public void deletedBinaryUsesTheSameIssuedTargetCasAndHasNoInventedSourceBody()throws Exception{Files.delete(files.resolve("asset.bin"));assertEquals("deleted",changed("asset.bin").getString("change"));assertTrue(changed("asset.bin").getBoolean("binary"));JSONObject shown=review("asset.bin");assertTrue(ProjectBinaryImport.isReview(shown));assertTrue(shown.getBoolean("deleted"));assertEquals("absent",shown.getString("expectedHash"));assertEquals(0,shown.getJSONObject("sourcePreview").getInt("shownBytes"));JSONObject receipt=apply(shown);assertEquals(2,receipt.getInt("version"));assertTrue(head("asset.bin").tombstone);assertNull(changed("asset.bin"));}
 @Test public void aMissingUnselectedSourceCannotDeleteAnIndependentlyAddedFormalBinary()throws Exception{workspace.writeBytesForHost(head("unselected.bin"),BEFORE);assertThrows(IllegalArgumentException.class,()->review("unselected.bin"));assertEquals(1,head("unselected.bin").version);assertArrayEquals(BEFORE,head("unselected.bin").bytes());}
 @Test public void theOriginalUtf8ReviewAndImportRemainTextAndTheByteMarkerCannotRelaxTheirLimits()throws Exception{Files.write(files.resolve("a.txt"),"new 中文\n".getBytes(StandardCharsets.UTF_8));JSONObject shown=review("a.txt");assertFalse(ProjectBinaryImport.isReview(shown));assertEquals("new 中文\n",shown.getString("content"));assertTrue(shown.getString("diff").contains("+new 中文"));JSONObject payload=input("a.txt").put("expectedHash",shown.getString("expectedHash")).put("expectedVersion",shown.getInt("expectedVersion"));assertEquals(2,local.handle("importToProject",payload).getInt("version"));assertEquals("new 中文\n",workspace.handle("read",new JSONObject().put("projectId",project).put("path","a.txt")).getString("content"));Files.write(files.resolve("a.txt"),"x".repeat(70000).getBytes(StandardCharsets.UTF_8));JSONObject longText=review("a.txt");assertFalse(longText.getBoolean("importable"));JSONObject forged=input("a.txt").put("byteReviewContract",ProjectBinaryImport.REVIEW).put("projectId",project).put("expectedHash",longText.getString("expectedHash")).put("expectedVersion",2).put("expectedTargetHash",head("a.txt").sha256).put("expectedTargetRevisionId",head("a.txt").revisionId);assertThrows(SecurityException.class,()->local.handle("importToProject",forged));assertEquals(2,head("a.txt").version);}
 @Test public void anAlreadyMatchingVersionCanExplicitlyRepairOnlyTheOriginalBaselineWithoutDuplicatingContent()throws Exception{Path metadata=files.getParent().resolve("checkout.json");JSONObject cache=JsonFiles.read(metadata.toFile());JSONArray rows=cache.getJSONArray("files");for(int i=0;i<rows.length();i++)if("asset.bin".equals(rows.getJSONObject(i).getString("path")))rows.getJSONObject(i).put("sourceVersion",0).put("sha256","absent");JsonFiles.write(metadata.toFile(),cache);String revision=head("asset.bin").revisionId;JSONObject shown=review("asset.bin");assertTrue(shown.getBoolean("same"));assertTrue(shown.getBoolean("baselineNeedsRefresh"));assertTrue(shown.getBoolean("importable"));JSONObject receipt=apply(shown);assertEquals("baseline_reconciled",receipt.getString("status"));assertFalse(receipt.getBoolean("contentWritten"));assertFalse(receipt.getBoolean("projectVersionCommitted"));assertTrue(receipt.getBoolean("alreadyMatchingVersionObserved"));assertEquals(1,head("asset.bin").version);assertEquals(revision,head("asset.bin").revisionId);assertFalse(review("asset.bin").getBoolean("importable"));assertEquals("unchanged",changed("asset.bin").getString("change"));}
 @Test public void symlinkOversizeAndClosedOwnerModuleNeverPublishTruncatedOrLateBytes()throws Exception{Files.delete(files.resolve("asset.bin"));Path other=Files.createTempFile("outside-binary-owner-",".bin");try{Files.write(other,new byte[]{0,9});Files.createSymbolicLink(files.resolve("asset.bin"),other);assertThrows(SecurityException.class,()->review("asset.bin"));Files.delete(files.resolve("asset.bin"));Files.write(files.resolve("asset.bin"),new byte[ProjectSources.MAX_FILE_BYTES+1]);assertThrows(SecurityException.class,()->review("asset.bin"));Files.write(files.resolve("asset.bin"),new byte[]{0,8});JSONObject shown=review("asset.bin");local.close();assertThrows(Exception.class,()->apply(shown));assertEquals(1,head("asset.bin").version);assertArrayEquals(BEFORE,head("asset.bin").bytes());}finally{Files.deleteIfExists(other);}}
}
